"""Browser WebAudio checks and audition WAVs generated by the actual game mixer.

No automated test claims to have listened to the music. Peak/RMS are measured,
not perceptual loudness; the WAVs are for a human headphone/speaker audition.
"""
import base64
import json
import math
from pathlib import Path
from playwright.sync_api import sync_playwright

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'output';OUT.mkdir(exist_ok=True)
errors=[]
HARNESS='''<!doctype html><meta charset="utf-8"><title>Audio QA</title>
<button id="enable">Enable from a real gesture</button><button id="voice">Play voice</button>
<script src="/src/audio.js"></script><script>
IslandAudio.set(true);document.getElementById('enable').onclick=()=>IslandAudio.set(true);
</script>'''
with sync_playwright() as p:
    browser=p.chromium.launch(channel='msedge',headless=True,args=['--autoplay-policy=user-gesture-required'])
    page=browser.new_page()
    page.on('pageerror',lambda error:errors.append(str(error)))
    page.route('**/audio-harness',lambda route:route.fulfill(content_type='text/html',body=HARNESS))
    page.goto('http://127.0.0.1:4173/audio-harness');page.wait_for_load_state('networkidle')
    before=page.evaluate('IslandAudio.snapshot()')
    assert before['contextState']=='uninitialized' and before['timerCount']==0,before
    page.locator('#enable').click();page.wait_for_timeout(350)
    unlocked=page.evaluate('IslandAudio.snapshot()')
    assert unlocked['contextState']=='running' and unlocked['timerCount']==1,unlocked
    # Repeated activation must not restart/stack the music transport.
    page.evaluate('for(let i=0;i<25;i++)IslandAudio.set(true)');page.wait_for_timeout(80)
    repeat=page.evaluate('IslandAudio.snapshot()')
    assert repeat['timerCount']==1 and repeat['schedulerStarts']==1,repeat
    page.evaluate('IslandAudio.setLevels({music:.4,sfx:.6,voice:.8});IslandAudio.duck(true)');page.wait_for_timeout(160)
    duck=page.evaluate('IslandAudio.snapshot()')
    assert abs(duck['gains']['duck']-10**(-11/20))<.015,duck
    assert abs(duck['gains']['sfx']-.6**1.6)<.015,duck
    page.evaluate('IslandAudio.duck(false)');page.wait_for_timeout(650)
    recovered=page.evaluate('IslandAudio.snapshot()')
    assert abs(recovered['gains']['duck']-1)<.005,recovered
    page.evaluate('IslandAudio.set(false)');page.wait_for_timeout(110)
    muted=page.evaluate('IslandAudio.snapshot()')
    assert muted['gains']['master']==0 and muted['timerCount']==0 and muted['liveSources']==0 and muted['contextState']=='suspended',muted
    # An immediate mute/unmute used to cancel cleanup and stack an old melody.
    page.evaluate('''async()=>{for(let i=0;i<12;i++){IslandAudio.set(true);await new Promise(r=>setTimeout(r,8));IslandAudio.set(false);}IslandAudio.set(true);}''')
    page.wait_for_timeout(800)
    rapid=page.evaluate('IslandAudio.snapshot()')
    assert rapid['timerCount']==1 and rapid['liveSources']<=70 and rapid['maxSources']<=128,rapid
    # Offline renders use exactly the live note/event synthesis and bus graph.
    renders=page.evaluate('''async()=>{
      const stats=buffer=>{let peak=0,sum=0,clip=0,hash=2166136261,count=0;for(let c=0;c<buffer.numberOfChannels;c++){const d=buffer.getChannelData(c);for(let i=0;i<d.length;i++){const x=d[i];if(!Number.isFinite(x))throw Error('nonfinite audio');peak=Math.max(peak,Math.abs(x));sum+=x*x;if(Math.abs(x)>=.999)clip++;if(i%37===0)hash=Math.imul(hash^Math.round(x*32767),16777619)>>>0;count++;}}return{peak,rms:Math.sqrt(sum/count),clippedSamples:clip,hash,samples:count};};
      const rms=(buffer,start,end)=>{const d=buffer.getChannelData(0),lo=Math.floor(start*buffer.sampleRate),hi=Math.floor(end*buffer.sampleRate);let sum=0;for(let i=lo;i<hi;i++)sum+=d[i]*d[i];return Math.sqrt(sum/(hi-lo));};
      const wav=buffer=>{const channels=buffer.numberOfChannels,length=buffer.length,bytes=new Uint8Array(44+length*channels*2),view=new DataView(bytes.buffer),put=(at,s)=>{for(let i=0;i<s.length;i++)bytes[at+i]=s.charCodeAt(i);};put(0,'RIFF');view.setUint32(4,bytes.length-8,true);put(8,'WAVE');put(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,channels,true);view.setUint32(24,buffer.sampleRate,true);view.setUint32(28,buffer.sampleRate*channels*2,true);view.setUint16(32,channels*2,true);view.setUint16(34,16,true);put(36,'data');view.setUint32(40,length*channels*2,true);for(let i=0;i<length;i++)for(let c=0;c<channels;c++)view.setInt16(44+(i*channels+c)*2,Math.round(Math.max(-1,Math.min(1,buffer.getChannelData(c)[i]))*32767),true);let text='';for(let i=0;i<bytes.length;i+=32768)text+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(text);};
      window.audioQA={wav};
      const music=await IslandAudio.renderPreview({duration:36,region:'home',phase:'day'}),sfx=await IslandAudio.renderPreview({duration:18,music:false,effects:true}),mixed=await IslandAudio.renderPreview({duration:10,levels:{music:1,sfx:1,voice:1},effects:true}),night=await IslandAudio.renderPreview({duration:12,region:'lake',phase:'night'});
      const normal=await IslandAudio.renderPreview({duration:4}),ducked=await IslandAudio.renderPreview({duration:4,duckAt:.5}),silent=await IslandAudio.renderPreview({duration:3,levels:{music:0,sfx:0},effects:true}),mute=await IslandAudio.renderPreview({duration:3,muteAt:.8});
      const effects={};for(const kind of ['button','dialogue','memory','wrong','jump','land','footstep','plant','water','paper_boat','stone_skip','windmill','sandcastle','swing','stroll','shutter','finale'])effects[kind]=stats(await IslandAudio.renderPreview({duration:2,music:false,effects:[kind]}));
      return {music:{...stats(music),wav:wav(music)},effectsPreview:{...stats(sfx),wav:wav(sfx)},night:{...stats(night),wav:wav(night)},mixed:stats(mixed),silent:stats(silent),mutedTailRms:rms(mute,1,3),duckRatio:rms(ducked,.75,2.4)/rms(normal,.75,2.4),effects};
    }''')
    for key,name in [('music','island-original-bgm-36s.wav'),('effectsPreview','island-interactions-18s.wav'),('night','moonlake-evening-12s.wav')]:
        (OUT/name).write_bytes(base64.b64decode(renders[key].pop('wav')))
    assert renders['music']['rms']>.008 and renders['music']['peak']<.9,renders['music']
    assert renders['mixed']['peak']<.95 and renders['mixed']['clippedSamples']==0,renders['mixed']
    assert renders['silent']['peak']==0 and renders['mutedTailRms']<1e-7,renders
    assert .24<renders['duckRatio']<.33,renders['duckRatio']
    assert len({v['hash'] for v in renders['effects'].values()})==len(renders['effects']),renders['effects']
    assert all(v['peak']>.005 and v['clippedSamples']==0 for v in renders['effects'].values()),renders['effects']
    # Route an actual HTML audio element through the voice bus.
    page.evaluate('''async()=>{const b=await IslandAudio.renderPreview({duration:2,music:false,effects:['memory']});window.testVoice=document.createElement('audio');testVoice.src='data:audio/wav;base64,'+audioQA.wav(b);testVoice.loop=true;document.body.append(testVoice);IslandAudio.setLevels(IslandAudio.defaults);IslandAudio.attachVoice(testVoice);document.getElementById('voice').onclick=()=>testVoice.play();}''')
    page.locator('#voice').click();page.wait_for_timeout(220)
    voice=page.evaluate('({...IslandAudio.snapshot(),voicePaused:testVoice.paused,voiceMuted:testVoice.muted})')
    assert not voice['voicePaused'] and not voice['voiceMuted'] and voice['gains']['duck']<.3 and voice['voiceElements']==1,voice
    page.evaluate('IslandAudio.setLevels({voice:0})');page.wait_for_timeout(160)
    voiceZero=page.evaluate('IslandAudio.snapshot()')
    assert voiceZero['gains']['voice']==0,voiceZero
    page.evaluate('IslandAudio.set(false)');page.wait_for_timeout(100)
    voiceMuted=page.evaluate('({...IslandAudio.snapshot(),voicePaused:testVoice.paused,voiceMuted:testVoice.muted})')
    assert voiceMuted['voicePaused'] and voiceMuted['voiceMuted'] and voiceMuted['gains']['master']==0,voiceMuted
    page.locator('#enable').click();page.wait_for_timeout(150)
    second=browser.new_page();second.goto('about:blank');second.bring_to_front();page.wait_for_timeout(150)
    nativeHidden=page.evaluate('document.hidden')
    if not nativeHidden:
        page.evaluate("Object.defineProperty(document,'hidden',{configurable:true,get:()=>true});document.dispatchEvent(new Event('visibilitychange'))")
        page.wait_for_timeout(100)
    background=page.evaluate('IslandAudio.snapshot()')
    assert background['contextState']=='suspended' and background['timerCount']==0 and background['liveSources']==0,background
    second.close();page.bring_to_front()
    if not nativeHidden:page.evaluate("delete document.hidden;document.dispatchEvent(new Event('visibilitychange'))")
    page.wait_for_timeout(250)
    foreground=page.evaluate('IslandAudio.snapshot()')
    assert foreground['contextState']=='running' and foreground['timerCount']==1,foreground
    page.evaluate('testVoice.remove()');page.wait_for_timeout(80)
    released=page.evaluate('IslandAudio.snapshot()');assert released['voiceElements']==0,released
    page.evaluate('IslandAudio.set(false)');page.wait_for_timeout(100)
    final=page.evaluate('IslandAudio.snapshot()')
    assert final['liveSources']==0 and final['timerCount']==0,final
    assert not errors,errors
    report={'activation':{'before':before,'unlocked':unlocked},'repeatedActivation':repeat,'duck':duck,'duckRecovered':recovered,'mute':muted,'rapidToggle':rapid,'renders':renders,'voice':voice,'voiceZero':voiceZero,'voiceMuted':voiceMuted,'background':background,'foreground':foreground,'visibilityMethod':'native browser tab' if nativeHidden else 'visibility handler with controlled hidden property','releasedVoice':released,'final':final,'browserErrors':errors,'listening':'Not auditioned by the agent; WAVs supplied for headphone/speaker listening.'}
    for name in ['music','effectsPreview','night','mixed']:
        report['renders'][name]['peakDbFS']=20*math.log10(report['renders'][name]['peak'])
        report['renders'][name]['rmsDbFS']=20*math.log10(report['renders'][name]['rms'])
    (OUT/'audio-v6-report.json').write_text(json.dumps(report,indent=2),encoding='utf-8')
    print(json.dumps({'music':renders['music'],'mixed':renders['mixed'],'duckRatio':renders['duckRatio'],'silentPeak':renders['silent']['peak'],'effectKinds':len(renders['effects']),'maxLiveSources':final['maxSources'],'finalSources':final['liveSources'],'visibilityMethod':report['visibilityMethod'],'browserErrors':errors}))
    browser.close()
